/-- For [the supplied quantities and conditions](hyp:epsSeq), the [fixed privacy](goal) is the mathematical object specified below. For [the displayed quantities and conditions](hyp:ε), these specify the stated inputs. -/
def FixedPrivacy (epsSeq : ℕ → ℝ) (ε : ℝ) : Prop :=
  0 < ε ∧ ∀ k, epsSeq k = ε

d8ab05808ee472a6.statement:
/-- For the supplied quantities and conditions, the upper envelope is the mathematical object specified below. [The upper Envelope](goal) is determined by [the displayed parameters](hyp:θ,p,ε,t). -/
def upperEnvelope (θ : TrialParameter) (p ε t : ℝ) : ℝ :=
  sSup {u : ℝ | ∃ α ∈ feasibleSet ε, u = informationObjective θ p ε α t}

6d39d0c015961e6a.statement:
/-- For the supplied quantities and conditions, the vertex envelope is the mathematical object specified below. [The vertex Envelope](goal) is determined by [the displayed parameters](hyp:θ,p,ε,t). -/
def vertexEnvelope (θ : TrialParameter) (p ε t : ℝ) : ℝ :=
  sSup {u : ℝ | ∃ α ∈ (feasibleSet ε).extremePoints ℝ,
    u = informationObjective θ p ε α t}

